<?php declare(strict_types=1); ?>
<section class="module-toolbar"><div><p class="module-intro">Personel kartları, departmanlar ve çalışma durumları.</p><span class="result-count"><?= count($employees) ?> personel</span></div><a class="btn primary action-link" href="index.php?page=employees&action=create">＋ Yeni personel</a></section><section class="panel customer-list-panel"><form class="filter-bar"><input type="hidden" name="page" value="employees"><input name="q" value="<?= kd_e($q) ?>" placeholder="Ad, soyad, personel kodu veya e-posta ara"><select name="status"><option value="">Tüm durumlar</option><option value="active">Aktif</option><option value="inactive">Pasif</option><option value="terminated">İşten ayrıldı</option></select><button class="btn secondary">Filtrele</button></form><div class="table-wrap"><table class="data-table"><thead><tr><th>Personel</th><th>Departman</th><th>Pozisyon</th><th>İşe giriş</th><th>Maaş</th><th>Durum</th></tr></thead><tbody><?php foreach($employees as $e): ?><tr><td><a class="customer-name" href="index.php?page=employees&action=view&id=<?= (int)$e['id'] ?>"><?= kd_e($e['first_name'].' '.$e['last_name']) ?></a><small class="table-sub"><?= kd_e($e['employee_code']) ?></small></td><td><?= kd_e($e['department_name']?:'—') ?></td><td><?= kd_e($e['position']?:'—') ?></td><td><?= kd_e($e['hire_date']?:'—') ?></td><td><?= number_format((float)$e['base_salary'],2,',','.') ?> <?= kd_e($e['currency']) ?></td><td><?= kd_e($e['employment_status']) ?></td></tr><?php endforeach; ?><?php if(!$employees): ?><tr><td colspan="6">Personel kaydı bulunmuyor.</td></tr><?php endif; ?></tbody></table></div></section>
